tasks.setup:
class Node { constructor(value, next = null) { this.value = value; this.next = next; } }
class LinkedList {
  constructor() { this.head = null; }
  push(value) { this.head = new Node(value, this.head); }
  getAtIndex(index) {
    let current = this.head;
    let hops = 0;
    for (let i = 0; i < index; i++) {
      if (current === null) return { value: null, hops };
      current = current.next;
      hops++;
    }
    return { value: current?.value, hops };
  }
}
const list = new LinkedList();
list.push(10); list.push(20); list.push(30);

